136	interface BulkChangePlanArgs { userIds: string[]; plan: PlanType; }
137	
138	export function useBulkChangePlan() {
139	  const supabase = createUntypedClient();
140	  const queryClient = useQueryClient();
141	  const { user } = useAuth();
142	
143	  return useMutation({
144	    mutationFn: async ({ userIds, plan }: BulkChangePlanArgs) => {
145	      if (!user) throw new Error("Not authenticated");
146	      const newLimit = plan === "agency" ? 500 : plan === "pro" ? 25 : 3;
147	      await Promise.all(
148	        userIds.map((userId) =>
149	          supabase.from("profiles").update({ plan, scan_limit: newLimit }).eq("id", userId).then(({ error }) => {
150	            if (error) throw new Error(error.message);
151	          })
152	        )
153	      );
154	      await writeAuditLog(user.id, "bulk_change_plan", "profile", "bulk", { user_ids: userIds, new_plan: plan, count: userIds.length });
155	    },
156	    onSuccess: (_, { userIds, plan }) => {
157	      toast.success(`Updated ${userIds.length} users to ${plan} plan`);
158	      queryClient.invalidateQueries({ queryKey: ["admin", "users"] });
159	      queryClient.invalidateQueries({ queryKey: ["admin", "stats"] });
160	    },
161	    onError: (error: Error) => { toast.error(`Bulk plan change failed: ${error.message}`); },
162	  });
163	}
